SELECT analytics_order_facts.customer_segment, SUM(analytics_order_facts.gross_revenue) AS gross_revenue FROM analytics_order_facts WHERE analytics_order_facts.year = 2024 AND analytics_order_facts.month = 2 AND analytics_order_facts.region = 'North' AND analytics_order_facts.channel = 'online' GROUP BY analytics_order_facts.customer_segment ORDER BY gross_revenue DESC, analytics_order_facts.customer_segment ASC LIMIT 12
